end
if ~exist('src400sym','var')
    src400sym = sqw('e:\SHARE\Fe\Data\sqw\sqw2024\Fe_ei401_align_sym3.sqw ');
end
hc = hor_config;
ll = hc.log_level;
hc.log_level = -2;

w2_000a = cut(src400sym,line_proj('offset',[0,0,1]),[-0.1,0.1],0.04,0.04,[95,105]);
plot(w2_000a);liny; lz 0 2;keep_figure; %[output:0823464a]
w2_000b = cut(src400sym,line_proj('offset',[0,0,1]),[-0.1,0.1],0.04,0.04,[45,55]);
plot(w2_000b);lz 0 2; keep_figure; %[output:171c725a]

data_path = 'e:\SHARE\Fe\Data\analysis\06_fit_with_J0\sym4D_cutsAndFits\' %[output:88164110]
